/**
 * Classify an API error into a single metric label based on its HTTP status code.
 * Any error without a status code matching an HTTP client (4xx) or server (5xx)
 * error is reported as a generic failure.
 */
export const observeApiError = (error: any, metricObserver: (status: MetricsApiStatusTypes) => void) => {
    if (!error) {
        metricObserver('failure');
        return;
    }

    const { status } = error;

    if (status >= 500) {
        metricObserver('5xx');
        return;
    }

    if (status >= 400) {
        metricObserver('4xx');
        return;
    }

    metricObserver('failure');
};

export default observeApiError;
"}

