describe('observeApiError', () => {
    let observed: MetricsApiStatusTypes[];
    const metricObserver = (status: MetricsApiStatusTypes) => {
        observed.push(status);
    };

    beforeEach(() => {
        observed = [];
    });

    it.each([400, 404, 429, 499])('reports 4xx for client error status %d', (status) => {
        observeApiError({ status }, metricObserver);
        expect(observed).toEqual(['4xx']);
    });

    it.each([500, 502, 503, 599])('reports 5xx for server error status %d', (status) => {
        observeApiError({ status }, metricObserver);
        expect(observed).toEqual(['5xx']);
    });

    it.each([undefined, null, '', 0, false])('reports failure for falsy error %p', (error) => {
        observeApiError(error, metricObserver);
        expect(observed).toEqual(['failure']);
    });

    it.each([undefined, null, 200, 301, 'foo'])('reports failure when status is not an error code %p', (status) => {
        observeApiError({ status }, metricObserver);
        expect(observed).toEqual(['failure']);
    });

    it('calls the observer exactly once', () => {
        const spy = jest.fn();
        observeApiError({ status: 500 }, spy);
        expect(spy).toHaveBeenCalledTimes(1);
    });
});
